script = r'''
const { readExcel } = require('./skills/OfficeBench/tools/excel');
const { llm }       = require('./skills/OfficeBench/tools/llm');
const { sendEmail }  = require('./skills/OfficeBench/tools/email');

(async () => {
  // 1. Read the Excel file
  const dataPath = './skills/OfficeBench/testbed/data/order_summary.xlsx';
  const rows = await readExcel(dataPath);
  console.log('Rows read:', rows.length);
  console.log('Sample (first 3):', JSON.stringify(rows.slice(0, 3), null, 2));

  // 2. Build a prompt and call the LLM to summarise
  const prompt = `You are a data analyst. Below is order data in JSON format. Please provide a concise executive summary of the data including: total number of orders, total revenue, top products or categories, any notable trends, and key statistics.\n\nData:\n${JSON.stringify(rows)}`;
  const summary = await llm(prompt);
  console.log('\n--- LLM Summary ---');
  console.log(summary);

  // 3. Email the summary
  const emailResult = await sendEmail({
    to: 'bob@example.com',
    subject: 'Order Summary Report',
    body: summary
  });
  console.log('\n--- Email Result ---');
  console.log(JSON.stringify(emailResult, null, 2));
})();
'''.strip()

await write_file('./run_order_summary.js', script)
print("Script written.")

result = await run_command("node ./run_order_summary.js")
print(result)
